 page.main('2026-09-23','data-rate-buydown-review-link','Compare the <a href="/blog/rate-buydown-str-investment/">points quote register, early-payoff screen and launch-liquidity worksheet</a> before choosing the lowest advertised mortgage rate.')
 p=page.ROOT/'blog'/page.SLUG/'index.html';s=p.read_text()
 s=re.sub(r'<span>Updated [^<]+</span>','<span>Updated October 7, 2026</span>',s,count=1)
 if '"@type": "FAQPage"' not in s:
  d={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in page.FAQ]}
